const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let i = 0;
const S = data[i++];
const T = data[i++];

const graph = Array.from({ length: S + 1 }, () => new Uint8Array(S + 1));

for (let j = 0; j < T; j++) {
  const x = data[i++];
  const y = data[i++];
  graph[x][y] = 1;
  graph[y][x] = 1;
}

const P = data[i++];
let possible = 0;

for (let j = 0; j < P; j++) {
  const N = data[i++];
  let previous = data[i++];
  let valid = true;

  for (let k = 1; k < N; k++) {
    const current = data[i++];
    if (!graph[previous][current]) valid = false;
    previous = current;
  }

  if (valid) possible++;
}

console.log(possible);
